{
  "chapter_proposals": [
    {
      "chapter_id": "CH1",
      "title": "物理界限：色散与几何对联合带宽 - 视场的双重约束",
      "purpose": "建立可见光消色差超透镜的理论性能基准，阐明单界面几何结构与相位/群延迟色散如何共同构成无法通过单纯优化纳米结构消除的硬性物理约束。本章旨在解释为何在大数值孔径（NA）下，同时实现大视场（FOV）和宽工作带宽在物理本质上存在互斥性，并定性描述由此产生的效率饱和趋势。",
      "scope": "聚焦于单层平面光学元件（single-interface elements）的物理极限。涵盖高 NA 下的几何像差硬约束（彗差、像散）、衍射效率随波长变化的普遍规律（sinc²律），以及宽视场条件下色散工程面临的带宽压缩与饱和效应。明确区分‘局部相互作用假设’下的理论上限与实际器件表现的差距。不包含多层堆叠系统或非平面光学的解决方案，除非用于反衬单界面的局限性。",
      "excluded_source_handles": [],
      "substantive_threads": [
        {
          "theme": "单界面几何导致的视场硬约束",
          "argument_structure": "基于 P0001 的论述，首先确立单界面衍射/折射元件在高 NA 条件下的固有缺陷。指出当 NA=0.5 时，由于缺乏额外的自由度来校正离轴像差（特别是彗差和像散），有效视场被严格限制在极小范围（如 < 5 µm）。论证这种限制源于几何光学的基本法则，而非制造工艺的不足，因此任何试图在单层结构内同时实现高 NA 和大 FOV 的努力都面临根本性的物理障碍。",
          "evidence_base": ["P0001"],
          "conditions_and_limits": "此结论严格适用于单界面元表面。若引入多层结构或体光学元件，该几何约束可能被缓解，但这已超出本章讨论的‘单界面物理极限’范畴。"
        },
        {
          "theme": "宽带效率的普遍律与解耦困难",
          "argument_structure": "阐述衍射元件效率随波长变化的 sinc²普遍规律。解释在连续波段内，焦距与波长的解耦需要精确的群延迟调控，而单一共振或波导模式往往难以在全波段维持理想的相位剖面。分析这种内在的色散特性如何导致在非设计波长处效率急剧下降，从而限制了可用带宽。",
          "evidence_base": ["P0001"],
          "conditions_and_limits": "虽然共振结构提供了额外的设计自由度，但其引入的模式耦合和损耗可能抵消部分增益。Sinc²律是一个理想化模型，实际效率还受材料吸收和散射影响。"
        },
        {
          "theme": "宽视场下的带宽饱和与非直观相位需求",
          "argument_structure": "结合 P0002 的理论框架（尽管具体公式不可用），定性论述在大 NA 和大 FOV 条件下，带宽受到的双重压缩效应。指出随着视场增加，为校正像差所需的群延迟空间分布变得极其复杂，导致可用带宽呈现饱和趋势，即增加 FOV 不再线性换取带宽，而是迅速触及理论天花板。特别分析有限孔径下掠入射时的非直观现象：最大相位需求未必出现在最大入射角处，这对传统基于边缘光线的设计直觉提出了挑战，暗示了简单缩放设计的失效。",
          "evidence_base": ["P0002"],
          "conditions_and_limits": "由于 P0002 全文解析失败，此处仅能描述‘带宽饱和’和‘非直观相位分布’的定性趋势，无法提供具体的临界条件公式或不同焦点定义下的定量差异曲线。需明确告知读者，精确的量化边界需参照原始文献 P0002。"
        }
      ],
      "supplement_requests": [],
      "directed_reads": [
        {
          "source_handle": "P0001",
          "focus": "提取关于单界面高 NA 下 FOV 限制的具体数值案例（如 NA=0.5 时的 FOV 大小），以及关于 sinc²效率律的物理机制描述。重点关注其对‘不公平比较’的批判逻辑，作为后续章节评估实证表现的伏笔。"
        },
        {
          "source_handle": "P0002",
          "focus": "确认关于‘带宽随 FOV 增加而饱和’的定性结论，以及‘有限孔径下掠入射相位需求最小化’的非直观现象描述。记录因工具失败而无法获取的具体数学表达式，以便在文中恰当标注局限性。"
        }
      ],
      "transition_logic": "本章确立了物理上限的刚性约束：单界面几何锁死了高 NA 下的视场，而色散工程在宽视场下遭遇带宽饱和。这些物理事实构成了所有设计尝试的背景板。下一章将转向‘设计机制’，探讨研究者如何通过复杂的色散补偿策略（如多重共振、几何相位等）试图逼近这些极限，并深入分析这些策略在斜入射或宽带条件下所引入的新代价（如效率下降、模式耦合），从而揭示理论与现实之间的权衡路径。"
    }
  ],
  "screened_sources": []
}

